package it.frociart.app;
import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import static it.frociart.app.FlowModel.*;
public final class ConsoleLogTests {
 static int checks;static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static String dec(String text){return new String(Base64.getDecoder().decode(text),StandardCharsets.UTF_8);}
 public static void main(String[] args)throws Exception{Path root=Paths.get(args[0]);for(String line:Files.readAllLines(root.resolve("cases.tsv"),StandardCharsets.UTF_8)){
  String[] row=line.split("\t",-1);String code=dec(row[1]),wanted=dec(row[3]);List<String> inputs=new ArrayList<>();if(row[4].contains("I"))for(String part:dec(row[2]).split(",",-1))inputs.add(dec(part));
  Document d=FlowPseudocode.decode(code);String before=FlowCodec.encode(d);FlowEngine.Runner run=new FlowEngine.Runner(d);int at=0;List<String[]> accepted=new ArrayList<>();
  for(int i=0;i<10000&&run.state!=FlowEngine.State.COMPLETED&&run.state!=FlowEngine.State.ERROR;i++){
   if(run.state==FlowEngine.State.WAITING){check(at<inputs.size(),"Fixture input available");int count=run.consoleLog.size();long revision=run.consoleLog.revision();String variable=run.inputVariable,node=run.currentNodeId,scope=run.currentFunctionId,prompt=run.inputPrompt;
    if(!row[0].equals("empty-text")&&!row[0].equals("unicode")){check(!run.submitInput("NaN"),"Invalid input rejected");check(run.consoleLog.size()==count&&run.consoleLog.revision()==revision&&run.state==FlowEngine.State.WAITING,"Retry never fabricates accepted input");}
    check(run.submitInput(inputs.get(at++)),"Valid input accepted");accepted.add(new String[]{variable,node,scope,prompt,Integer.toString(run.steps)});
   }else run.step();
  }
  check(run.state==(row[0].equals("error-after-input")?FlowEngine.State.ERROR:FlowEngine.State.COMPLETED),"Exact state "+row[0]);check(run.outputText().replace("\r\n","\n").equals(wanted),"Original output bytes/continuation "+row[0]);List<FlowConsoleLog.Entry> entries=run.consoleLog.snapshot();StringBuilder kinds=new StringBuilder();for(FlowConsoleLog.Entry e:entries)kinds.append(e.kind==FlowConsoleLog.EntryKind.INPUT?'I':'O');check(kinds.toString().equals(row[4]),"Chronological I/O "+row[0]);int n=0,outputs=0;
  for(FlowConsoleLog.Entry e:entries){boolean found=false;for(Document g:FlowFunctionEditing.graphs(d))for(Node node:g.nodes)found|=node.id.equals(e.nodeId);check(e.step>0&&found,"Actual executed origin/step");check(run.consoleLog.find(e.sequence)==e,"Stable event identity");
   if(e.kind==FlowConsoleLog.EntryKind.INPUT){String[] a=accepted.get(n++);check(e.variable.equals(a[0])&&e.nodeId.equals(a[1])&&Objects.equals(e.functionId,a[2])&&e.prompt.equals(a[3])&&e.step==Integer.parseInt(a[4]),"Input context captured before advance");}
   else{check(e.text.equals(run.output.get(outputs))&&e.newline==run.outputNewlines.get(outputs),"Exact output text/flags");outputs++;}
  }
  check(n==at&&outputs==run.output.size(),"No duplicate input or output");if(row[0].equals("nested"))check(entries.get(1).functionName.equals("chiedi")&&entries.get(1).functionId.equals(d.functions.get(0).id),"Nested input scope");if(row[0].equals("vector"))check(entries.get(0).variable.equals("v[1]"),"Indexed input target");
  String text=run.consoleLog.toText();Files.write(root.resolve("android-"+row[0]+".txt"),text.getBytes(StandardCharsets.UTF_8));check(FlowCodec.encode(d).equals(before),"History never added to project persistence");check(text.equals(new String(Files.readAllBytes(root.resolve("pc-"+row[0]+".txt")),StandardCharsets.UTF_8)),"Exact shared text transcript "+row[0]);int steps=run.steps;String output=run.outputText();FlowEngine.State state=run.state;Map<String,FlowEngine.Value> variables=new LinkedHashMap<>(run.variables);long sequence=entries.isEmpty()?0:entries.get(entries.size()-1).sequence;
  run.consoleLog.clear();check(run.consoleLog.size()==0&&run.consoleLog.discarded()==0&&run.consoleLog.toText().equals(""),"Explicit clear resets only history");check(run.steps==steps&&run.state==state&&run.outputText().equals(output)&&run.variables.equals(variables),"Clear preserves complete execution state");check(entries.size()==row[4].length()&&run.consoleLog.find(sequence)==null,"Snapshot immutable after clear");run.reset();check(run.consoleLog.size()==0&&run.steps==0&&run.outputText().equals(""),"Reset starts fresh console");System.out.println("PASS console "+row[0]);
 }
 FlowConsoleLog log=new FlowConsoleLog();for(int i=0;i<10000;i++)log.add(FlowConsoleLog.EntryKind.OUTPUT,"",null,null,"n",null,"Principale",i,true);check(log.size()==FlowConsoleLog.MAX_ENTRIES&&log.discarded()==10000-FlowConsoleLog.MAX_ENTRIES,"Bounded ring retains latest events");check(log.get(0).step==10000-FlowConsoleLog.MAX_ENTRIES&&log.get(log.size()-1).step==9999,"Eviction keeps chronological tail");check(log.toText().contains("messaggi precedenti rimossi"),"Retention explicit in copied/saved history");long sequence=log.get(0).sequence;log.clear();log.add(FlowConsoleLog.EntryKind.INPUT,"x","?","x","n",null,"Principale",1,true);check(log.find(sequence)==null,"Clear never reuses old identity");
 log.clear();String large=String.join("",Collections.nCopies(2048,"a"));for(int i=0;i<1000;i++)log.add(FlowConsoleLog.EntryKind.INPUT,large,"Domanda","nome","n",null,"Principale",i,true);int cost=0;for(FlowConsoleLog.Entry e:log.snapshot())cost+=e.cost;check(log.size()<1000&&log.discarded()>0&&cost<=FlowConsoleLog.MAX_CHARACTERS,"Input history character budget");check(log.get(log.size()-1).step==999,"Most recent accepted input retained");log.clear();log.add(FlowConsoleLog.EntryKind.OUTPUT,String.join("",Collections.nCopies(FlowConsoleLog.MAX_CHARACTERS-12,"a"))+"🐢Z",null,null,"n",null,"Principale",1,false);check(log.size()==1&&log.get(0).textLimited&&log.toText().contains("Testo limitato"),"Defensive truncation explicit");String retained=log.get(0).text;check(retained.isEmpty()||!Character.isHighSurrogate(retained.charAt(retained.length()-1)),"No split surrogate");System.out.println("CONSOLE_ANDROID_CORE PASS checks="+checks);
 }
}
